const { Pool } = require('pg');

// Create a database connection pool
let pool;

function initPool() {
  // Use DATABASE_URL from environment or .env.test
  const databaseUrl = process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production';

  pool = new Pool({
    connectionString: databaseUrl,
    // Additional pool configuration
    max: 5, // maximum number of clients in the pool
    idleTimeoutMillis: 30000,
    connectionTimeoutMillis: 5000,
  });

  // Handle pool errors
  pool.on('error', (err) => {
    console.error('Unexpected error on idle client', err);
  });
}

/**
 * Check database connectivity
 * @returns {Promise<boolean>} true if database is reachable
 */
async function checkDatabaseHealth() {
  if (!pool) {
    initPool();
  }

  try {
    // Try to execute a simple query
    const client = await pool.connect();
    const result = await client.query('SELECT 1 as health_check');
    client.release();
    return true;
  } catch (error) {
    console.error('Database health check failed:', error.message);
    return false;
  }
}

/**
 * Close the database pool
 */
async function closePool() {
  if (pool) {
    await pool.end();
    pool = null;
  }
}

module.exports = {
  initPool,
  checkDatabaseHealth,
  closePool,
  getPool: () => pool,
};

