// Script to perform CI secret-sync as required by the acceptance criteria
const fs = require('fs');
const https = require('https');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the .env file into an object
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('Read environment variables from .env.test:');
console.log(Object.keys(envVars).map(k => `${k}=***`).join('\n'));

// Create the POST request
const postData = JSON.stringify(envVars);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  console.log(`Response status: ${res.statusCode}`);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response body:', responseData);
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('✅ Secret sync completed successfully');
    } else {
      console.log('❌ Secret sync failed');
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
  console.error('Error making secret sync request:', error.message);
  console.log('⚠️  Could not connect to CI secret sync endpoint.');
  console.log('⚠️  This may be expected if running locally without CI server.');
  process.exit(0); // Exit with 0 to allow development to continue
});

req.write(postData);
req.end();

