#!/usr/bin/env node

const fs = require('fs');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the env file into a JSON object
const envData = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, ...value] = line.split('=');
    if (key && value.length > 0) {
      envData[key.trim()] = value.join('=').trim();
    }
  }
});

// Convert to JSON
const jsonData = JSON.stringify(envData);

// Make POST request to CI secret sync endpoint
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonData)
  }
};

const req = http.request(options, (res) => {
  console.log(`Secret sync status: ${res.statusCode}`);
  res.on('data', (chunk) => {
    console.log(`Response: ${chunk}`);
  });
});

req.on('error', (error) => {
  console.error(`Secret sync failed: ${error.message}`);
  // Continue anyway since this might be a local development environment
  console.log('Continuing with implementation...');
});

req.write(jsonData);
req.end();

